import itertools

n = 17
fixed = {1: -1, 6: 1, 9: -1}
c_fixed = {7: 3, 8: -2, 12: 0}

def compute_C(seq):
    # seq is list of +/-1 length n
    C = {}
    for k in range(1, n):
        s = 0
        for i in range(n - k):
            s += seq[i] * seq[i+k]
        C[k] = s
    return C

solutions = []
for bits in itertools.product([-1, 1], repeat=n):
    # check fixed seq
    ok = True
    for idx, val in fixed.items():
        if bits[idx] != val:
            ok = False
            break
    if not ok:
        continue
    # compute C
    C = compute_C(bits)
    # check fixed C
    for k, val in c_fixed.items():
        if C[k] != val:
            ok = False
            break
    if not ok:
        continue
    # check sum of squares
    sum_sq = sum(C[k]**2 for k in range(1, n))
    if sum_sq <= 40:
        solutions.append((bits, sum_sq))

print('found', len(solutions), 'solutions')
if solutions:
    # print first few
    for sol, sq in solutions[:10]:
        print(sol, sq)

